//! GENERATED by scripts/gen_tool_metadata.py — do not edit by hand.
//! Regenerate after changing any mode manifest:
//!     python scripts/gen_tool_metadata.py
//!
//! Label + tooltip + archetype icon for every ribbon tool id referenced
//! by the mode manifests (crates/engine/modes/*.toml). Wired ids mirror
//! the built-in ribbon's exact labels/tooltips; aspirational ("dream")
//! ids get derived metadata. `tool-icon()` in ribbon.slint resolves the
//! icon id to an SVG; a studio_modes test asserts full coverage.

/// Display metadata for one ribbon tool button.
pub struct ToolMeta {
    pub label: &'static str,
    pub tooltip: &'static str,
    pub icon: &'static str,
    /// True when clicking this actually does something today.
    /// False = a deliberate "dream" button: it renders fully but
    /// has no dispatch arm, so the UI must say so honestly and the
    /// click is counted as demand (see `usage_telemetry.rs`).
    pub wired: bool,
}

